options.onValidate:
const _this = this

async function getOptions () {
  const data = await $api.post('/docpalType/settings/check/duplicate', {
    name: value
  }).then(res => res.data.data)
  return data
}
async function validate () {
  const isDuplicate = await getOptions()
  console.log({isDuplicate})
  if (isDuplicate) {
    callback(new Error($t('tip.duplicate')))  //fail
  } 
  else if(!/^[a-zA-Z_]/.test(value)) {
    callback(new Error('Start with a letter or underscore.')) 
  }
  else if(!/^[a-zA-Z_][a-zA-Z0-9 _-]*$/.test(value)) {
    callback(new Error('Only letters, numbers, spaces , connectors and underscores can be entered')) 
  }
  else {
    callback();  //pass
  }
}
validate()

options.onMounted:
const _this = this
async function getOptions () {
  const data = await $api.get('/docpalType/settings/categories').then(res => res.data.data)
  const options = data.reduce((prev,item) => {
    prev.push({
      label: item,
      value: item
    })
    return prev
  }, [])
  _this.loadOptions(options.sort((a,b)=> (a.label.localeCompare(b.label) )))
}
getOptions()
